(2330594, 321017, 43774, '<td valign="top">The lighting in this really distracts from the baby</td>', 'The lighting in this really distracts from the baby', '2006-04-20 20:18:32.000000', NULL, 1),
(2330598, 322153, 43774, '<td valign="top">Image looks way over saturated and over sharpened. A more subtle approach would work better.</td>', 'Image looks way over saturated and over sharpened. A more subtle approach would work better.', '2006-04-20 20:19:07.000000', NULL, 1),
