(2330668, 322574, 15976, '<td valign="top">This is a classy picture. Very well done. A photographer that can relate to his subjects.</td>', 'This is a classy picture. Very well done. A photographer that can relate to his subjects.', '2006-04-20 20:47:44.000000', NULL, 1),
(2330680, 322384, 51538, '<td valign="top">Nice depth of field in the daffodil cups.  Not the easiest flower to photograph - although certainly the easiest to find in spring.</td>', 'Nice depth of field in the daffodil cups.  Not the easiest flower to photograph - although certainly the easiest to find in spring.', '2006-04-20 20:53:49.000000', NULL, 1),
(2330687, 321107, 43156, '<td valign="top">Excellent depth of field and view angle.</td>', 'Excellent depth of field and view angle.', '2006-04-20 20:55:50.000000', NULL, 1),
(2330691, 322403, 51538, '<td valign="top">Cercis or Judas Tree, I presume.  A lovely sign of spring.  The colloquial name implies an association with new life at Easter.</td>', 'Cercis or Judas Tree, I presume.  A lovely sign of spring.  The colloquial name implies an association with new life at Easter.', '2006-04-20 20:56:37.000000', NULL, 1),
