(2331018, 322909, 40580, '<td valign="top">Nice shot.  Background is a little distracting, but what can you do when you have a once-in-a-life-time shot.  I would''ve loved to seen this from the side to show them stacked more.</td>', 'Nice shot.  Background is a little distracting, but what can you do when you have a once-in-a-life-time shot.  I would''ve loved to seen this from the side to show them stacked more.', '2006-04-20 22:29:41.000000', NULL, 1),
(2331025, 321052, 40580, '<td valign="top">I love witty pictures.  Nice shot.</td>', 'I love witty pictures.  Nice shot.', '2006-04-20 22:31:28.000000', NULL, 1),
(2331047, 322973, 11854, '<td valign="top">LOL</td>', 'LOL', '2006-04-20 22:46:46.000000', NULL, 1),
(2331053, 323169, 48120, '<td valign="top">I wish this had been more in focus.  It would have been spectacular.</td>', 'I wish this had been more in focus.  It would have been spectacular.', '2006-04-20 22:48:53.000000', NULL, 1),
