INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2333181, 322237, 35994, '<td valign="top">nice composition</td>', 'nice composition', '2006-04-21 16:23:19.000000', NULL, 1),
(2333217, 321997, 35994, '<td valign="top">Adorable pic, I''m sure she''ll be well guarded by her new friend!</td>', 'Adorable pic, I''m sure she''ll be well guarded by her new friend!', '2006-04-21 16:40:04.000000', NULL, 1),
(2333267, 322640, 56243, '<td valign="top">LOL</td>', 'LOL', '2006-04-21 17:17:54.000000', NULL, 1),
(2333271, 321578, 56243, '<td valign="top">cute effect.  glad to see I''m not the only one who uses coffee cups.  May have been cuter if there were already some eggs on the towel finished.</td>', 'cute effect.  glad to see I''m not the only one who uses coffee cups.  May have been cuter if there were already some eggs on the towel finished.', '2006-04-21 17:20:32.000000', NULL, 1),
(2333289, 323124, 21197, '<td valign="top">Nice soft focus</td>', 'Nice soft focus', '2006-04-21 17:29:10.000000', NULL, 1),
(2333333, 323057, 56712, '<td valign="top">HOW did you do this shot? it lookes extremely cool!</td>', 'HOW did you do this shot? it lookes extremely cool!', '2006-04-21 17:41:58.000000', NULL, 1),
(2333359, 322320, 21197, '<td valign="top">Nice ''IR'' is it psuedo IR? Even if it''s a great photograph... My only 10 so far. You must do a tutorial.<br/> <br/>-Rick</td>', 'Nice ''IR'' is it psuedo IR? Even if it''s a great photograph... My only 10 so far. You must do a tutorial. -Rick', '2006-04-21 17:53:46.000000', NULL, 1),
(2333418, 322153, 24991, '<td valign="top">Not really into the over saturated colors.</td>', 'Not really into the over saturated colors.', '2006-04-21 18:22:31.000000', NULL, 1),
(2333421, 321519, 24991, '<td valign="top">So...why</td>', 'So...why', '2006-04-21 18:22:57.000000', NULL, 1),
(2333504, 322895, 57229, '<td valign="top">Title''s way off. Looks pretty new though. Well set up, clean image of a mundane object.</td>', 'Title''s way off. Looks pretty new though. Well set up, clean image of a mundane object.', '2006-04-21 19:00:38.000000', NULL, 1),
(2333512, 320134, 57229, '<td valign="top">I love flowers. Not much done with this to raise it above the ordinary, but it do look good. The little bud helps a lot, but otherwise more needs to be done with the composition, I think. Beware of subjects in the center...</td>', 'I love flowers. Not much done with this to raise it above the ordinary, but it do look good. The little bud helps a lot, but otherwise more needs to be done with the composition, I think. Beware of subjects in the center...', '2006-04-21 19:02:51.000000', NULL, 1),
(2333517, 323216, 57229, '<td valign="top">Works on a picture-telling-stories level. Not so much by the way of eye candy though.</td>', 'Works on a picture-telling-stories level. Not so much by the way of eye candy though.', '2006-04-21 19:04:22.000000', NULL, 1),
(2333522, 321955, 57229, '<td valign="top">New? jada jada. But what a beautiful image. Maybe you could have cropped and tilted a bit so you didn''t have <b>quite</b> so much dead space up to the right there, but trust old mother nature for some powerful forms.</td>', 'New? jada jada. But what a beautiful image. Maybe you could have cropped and tilted a bit so you didn''t have quite so much dead space up to the right there, but trust old mother nature for some powerful forms.', '2006-04-21 19:07:14.000000', NULL, 1),
(2333527, 322950, 57229, '<td valign="top">Pretty dynamic. The leaves are only new because you say so though. Too much dead space. Plusses for the image, minuses for the relevance to context.</td>', 'Pretty dynamic. The leaves are only new because you say so though. Too much dead space. Plusses for the image, minuses for the relevance to context.', '2006-04-21 19:09:16.000000', NULL, 1),
(2333535, 323086, 57229, '<td valign="top">Indeed it does. Needs just a little more depth of field on the flower and the two ends of this picture could just be lopped off. There''s quite a nice idea with the thrusting new bloom, but I don''t think this picture succeeds in graphically supporting the text of the title.</td>', 'Indeed it does. Needs just a little more depth of field on the flower and the two ends of this picture could just be lopped off. There''s quite a nice idea with the thrusting new bloom, but I don''t think this picture succeeds in graphically supporting the text of the title.', '2006-04-21 19:13:02.000000', NULL, 1),
(2333537, 320603, 57229, '<td valign="top">Cliché like nobody''s business, but a cracking sharp image and great colours. Sort of new, I guess.</td>', 'Cliché like nobody''s business, but a cracking sharp image and great colours. Sort of new, I guess.', '2006-04-21 19:14:46.000000', NULL, 1),
(2333540, 323224, 57229, '<td valign="top">There''s too much exciting stuff going on that leads the eye away from the saddle, I think. That''s mostly about the relevance of the title though. Great advert for rodeo aesthetics.</td>', 'There''s too much exciting stuff going on that leads the eye away from the saddle, I think. That''s mostly about the relevance of the title though. Great advert for rodeo aesthetics.', '2006-04-21 19:17:11.000000', NULL, 1),
(2333545, 321387, 57229, '<td valign="top">The green''s over-edited. It looks more like a disease than fresh turf. Tough call, because fresh spring stuff really does look as though it''s glowing sometimes, but I say this one didn''t make it, sorry. Good lines.</td>', 'The green''s over-edited. It looks more like a disease than fresh turf. Tough call, because fresh spring stuff really does look as though it''s glowing sometimes, but I say this one didn''t make it, sorry. Good lines.', '2006-04-21 19:19:27.000000', NULL, 1),
(2333549, 323161, 57229, '<td valign="top">Nice idea, but I think you''ve lost the texture. It takes a while to recognise that they''re wood shavings.</td>', 'Nice idea, but I think you''ve lost the texture. It takes a while to recognise that they''re wood shavings.', '2006-04-21 19:20:44.000000', NULL, 1),
(2333551, 322837, 57229, '<td valign="top">Nice start!</td>', 'Nice start!', '2006-04-21 19:21:17.000000', NULL, 1),
(2333554, 322357, 57229, '<td valign="top">Just about nothing new about this, but a well set up and composed picture with a mood. There isn''t a 23 on the scale...</td>', 'Just about nothing new about this, but a well set up and composed picture with a mood. There isn''t a 23 on the scale...', '2006-04-21 19:23:38.000000', NULL, 1),
(2333555, 321307, 57229, '<td valign="top">Points for purty...</td>', 'Points for purty...', '2006-04-21 19:24:02.000000', NULL, 1),
(2333560, 323214, 57229, '<td valign="top">Neat pic. I wish this was a no-editing challenge, but hey, still a good image.</td>', 'Neat pic. I wish this was a no-editing challenge, but hey, still a good image.', '2006-04-21 19:26:43.000000', NULL, 1),
(2333562, 321310, 57229, '<td valign="top">Cruel humour. I''ll sponsor a guardian angel for that one.</td>', 'Cruel humour. I''ll sponsor a guardian angel for that one.', '2006-04-21 19:28:05.000000', NULL, 1),
(2333775, 323222, 47852, '<td valign="top">Cute idea.. but I''d rather see this little guys expression when he''s excited about finding that first egg.</td>', 'Cute idea.. but I''d rather see this little guys expression when he''s excited about finding that first egg.', '2006-04-21 21:04:05.000000', NULL, 1),
(2333792, 322140, 47852, '<td valign="top">Adorable!  That little face peeking upward is priceless!</td>', 'Adorable!  That little face peeking upward is priceless!', '2006-04-21 21:10:05.000000', NULL, 1),
(2333797, 322092, 47852, '<td valign="top">How long did your poor model have to stand out there in the rain to get this shot?  Well captured expression and stance that portrays a definate energy.  Love the raindrops too!</td>', 'How long did your poor model have to stand out there in the rain to get this shot?  Well captured expression and stance that portrays a definate energy.  Love the raindrops too!', '2006-04-21 21:10:41.000000', NULL, 1),
(2333867, 322043, 53572, '<td valign="top">wonderful image.  how early is he/she?  i think it would be a better image if it was croped to avoid the blanket, a square  might work well here.  also, it''s too bad that soother''s in focus and not he eyes.</td>', 'wonderful image.  how early is he/she?  i think it would be a better image if it was croped to avoid the blanket, a square  might work well here.  also, it''s too bad that soother''s in focus and not he eyes.', '2006-04-21 21:36:00.000000', NULL, 1),
(2333882, 322579, 8367, '<td valign="top">What a cutie. Looks very young. Nice capture.</td>', 'What a cutie. Looks very young. Nice capture.', '2006-04-21 21:44:07.000000', NULL, 1),
(2334016, 321795, 55153, '<td valign="top">Great perspective on this.  There''s something really cool about this shot!</td>', 'Great perspective on this.  There''s something really cool about this shot!', '2006-04-21 22:31:48.000000', NULL, 1),
(2334024, 322384, 55153, '<td valign="top">I love the colors and the perspective of the shot.  Nice job!</td>', 'I love the colors and the perspective of the shot.  Nice job!', '2006-04-21 22:37:38.000000', NULL, 1),
(2334033, 322241, 46097, '<td valign="top">Nice depth of field and colours. The heavy shadows on the lower blooms have reduced the score somewhat.</td>', 'Nice depth of field and colours. The heavy shadows on the lower blooms have reduced the score somewhat.', '2006-04-21 22:42:39.000000', NULL, 1),
(2334036, 321476, 46097, '<td valign="top">Lovely photo......very cute subjects, answering the challenge theme very well. The impact of the whole photo is strengthened, by all your ducks being in formation. My only nitpick, if I have to look for one, is that the bright reflections slightly distract my attention....perhaps try darkening the water, if youre a photoshop guru.</td>', 'Lovely photo......very cute subjects, answering the challenge theme very well. The impact of the whole photo is strengthened, by all your ducks being in formation. My only nitpick, if I have to look for one, is that the bright reflections slightly distract my attention....perhaps try darkening the water, if youre a photoshop guru.', '2006-04-21 22:46:00.000000', NULL, 1),
(2334073, 321330, 57636, '<td valign="top">I like the redness.</td>', 'I like the redness.', '2006-04-21 23:15:17.000000', NULL, 1),
(2334077, 321625, 57636, '<td valign="top">I like the butterfly.</td>', 'I like the butterfly.', '2006-04-21 23:18:38.000000', NULL, 1),
(2334080, 322584, 57636, '<td valign="top">The baby is cute!</td>', 'The baby is cute!', '2006-04-21 23:22:55.000000', NULL, 1),
(2334082, 323164, 57636, '<td valign="top">I like the color of your flower!</td>', 'I like the color of your flower!', '2006-04-21 23:26:04.000000', NULL, 1),
(2334087, 323090, 57636, '<td valign="top">It`s beautiful.</td>', 'It`s beautiful.', '2006-04-21 23:27:35.000000', NULL, 1),
(2334092, 322607, 40667, '<td valign="top">Lmao... can you spell endorsment.... I can''t ;-)</td>', 'Lmao... can you spell endorsment.... I can''t ;-)', '2006-04-21 23:32:29.000000', NULL, 1),
(2334093, 322320, 57636, '<td valign="top">It looks like winter and it is a nice effect.</td>', 'It looks like winter and it is a nice effect.', '2006-04-21 23:32:35.000000', NULL, 1),
(2334095, 321955, 40667, '<td valign="top">Omg, too cool! really like this one, great DOF, i really like it!</td>', 'Omg, too cool! really like this one, great DOF, i really like it!', '2006-04-21 23:33:29.000000', NULL, 1),
(2334097, 321695, 40667, '<td valign="top">Interesting! gota giveyah that! actually really interesting photo, grabs ur attention, just like you want it too! U can''t Help but love photos like that! Nice job... and i''m not sure why... but i like the purple tinge at the bottom ;-)</td>', 'Interesting! gota giveyah that! actually really interesting photo, grabs ur attention, just like you want it too! U can''t Help but love photos like that! Nice job... and i''m not sure why... but i like the purple tinge at the bottom ;-)', '2006-04-21 23:35:54.000000', NULL, 1),
(2334100, 322895, 40667, '<td valign="top">I was sooo gona do this with my Nano... then decided against it. It''s so hard to take a proper product shot, but i like your lighting! really wouldhave poped more if you had used a white backdrop!! definatly try it, i know you''ll love the results</td>', 'I was sooo gona do this with my Nano... then decided against it. It''s so hard to take a proper product shot, but i like your lighting! really wouldhave poped more if you had used a white backdrop!! definatly try it, i know you''ll love the results', '2006-04-21 23:38:17.000000', NULL, 1),
(2334103, 322989, 40667, '<td valign="top">:-O ONLY 83 SONGS!! lol, sorry, I''ve got over 300 on mine. Nice shot, really would have liked to see the ipod more in focus... it''s a really clever idea, but inorder for it to work to your full advantage, you should try and make the song the main focal point of your photo IMO</td>', ':-O ONLY 83 SONGS!! lol, sorry, I''ve got over 300 on mine. Nice shot, really would have liked to see the ipod more in focus... it''s a really clever idea, but inorder for it to work to your full advantage, you should try and make the song the main focal point of your photo IMO', '2006-04-21 23:41:40.000000', NULL, 1),
(2334106, 322822, 40667, '<td valign="top">haha, wow are you ever playing the cute fuzzy little animal card ;-) lol, actually, i really like it! and wow... i think the cute fuzzy little animal card''s workin... well ;-)</td>', 'haha, wow are you ever playing the cute fuzzy little animal card ;-) lol, actually, i really like it! and wow... i think the cute fuzzy little animal card''s workin... well ;-)', '2006-04-21 23:43:35.000000', NULL, 1),
(2334112, 322248, 40667, '<td valign="top">Interesting photo for sure, just wondering what it has to do with new? I like the angle, and the DOF is definatly appealing. Wish i could see a larger version... looks good!</td>', 'Interesting photo for sure, just wondering what it has to do with new? I like the angle, and the DOF is definatly appealing. Wish i could see a larger version... looks good!', '2006-04-21 23:47:19.000000', NULL, 1),
(2334114, 322281, 40667, '<td valign="top">Omg, another one playing the cute fuzzy little animal card ;-) Omg, it alwayse works... alwayse ;-) we only have black squirrels up here... hmmm... i like it tho! definatly!</td>', 'Omg, another one playing the cute fuzzy little animal card ;-) Omg, it alwayse works... alwayse ;-) we only have black squirrels up here... hmmm... i like it tho! definatly!', '2006-04-21 23:48:20.000000', NULL, 1),
(2334119, 323057, 40667, '<td valign="top">Really like it!! lol, is that a soft box, umbrella or a celing light ;-) Nice job!</td>', 'Really like it!! lol, is that a soft box, umbrella or a celing light ;-) Nice job!', '2006-04-21 23:49:58.000000', NULL, 1),
(2334122, 322852, 40667, '<td valign="top">Lol, love it! brings back memories of my pet turtles ;-D</td>', 'Lol, love it! brings back memories of my pet turtles ;-D', '2006-04-21 23:51:14.000000', NULL, 1),
(2334151, 321795, 41574, '<td valign="top">I think a shallower depth of field could have helped bring out this subject; also, I''d have liked to see a tighter crop. Nonetheless, it''s a pretty shot.</td>', 'I think a shallower depth of field could have helped bring out this subject; also, I''d have liked to see a tighter crop. Nonetheless, it''s a pretty shot.', '2006-04-22 00:03:35.000000', NULL, 1),
(2334155, 320887, 41574, '<td valign="top">Ummm...yeah, I don''t think this really goes (at all) with the theme of this challenge. You might rack up some points with diehard "LOTR" fans, but I''m going to have to give this "stretch" a low score for being totally inconsiderate of the guidelines.</td>', 'Ummm...yeah, I don''t think this really goes (at all) with the theme of this challenge. You might rack up some points with diehard "LOTR" fans, but I''m going to have to give this "stretch" a low score for being totally inconsiderate of the guidelines.', '2006-04-22 00:04:50.000000', NULL, 1),
(2334161, 321925, 41574, '<td valign="top">I see what appears to be a leaf of lettuce (poorly in focus) the top part of which is over-exposed, and the rest of which (along with the entirety of the photograph) is indiscernible.</td>', 'I see what appears to be a leaf of lettuce (poorly in focus) the top part of which is over-exposed, and the rest of which (along with the entirety of the photograph) is indiscernible.', '2006-04-22 00:06:42.000000', NULL, 1),
(2334177, 323066, 41574, '<td valign="top">The shot looks over-processed to me, but, nevertheless, I find it to be a good, solid photograph.</td>', 'The shot looks over-processed to me, but, nevertheless, I find it to be a good, solid photograph.', '2006-04-22 00:12:08.000000', NULL, 1),
(2334183, 322030, 41574, '<td valign="top">I find very distracting the shallow depth of field you''ve used, as it totally blurs the top half of the flower. It''s still a good picture, but it leaves something significant to be desired. You might have used a narrower aperture, or focused at an interim portion of the subject, so to leave more of it at both ends in the circle of confusion.</td>', 'I find very distracting the shallow depth of field you''ve used, as it totally blurs the top half of the flower. It''s still a good picture, but it leaves something significant to be desired. You might have used a narrower aperture, or focused at an interim portion of the subject, so to leave more of it at both ends in the circle of confusion.', '2006-04-22 00:14:44.000000', NULL, 1),
(2334188, 322237, 41574, '<td valign="top">I think this is a bit of a stretch for the challenge, but feel, too, that it just manages to work. Technically, I very much appreciate the picture.</td>', 'I think this is a bit of a stretch for the challenge, but feel, too, that it just manages to work. Technically, I very much appreciate the picture.', '2006-04-22 00:15:51.000000', NULL, 1),
(2334197, 322687, 41574, '<td valign="top">I love the vibrant greens of the picture; they contrast wonderfully with the background...which looks, actually, B&amp;W. Is this image the result of selective-color processing? If so, is such editing allowed in this challenge?</td>', 'I love the vibrant greens of the picture; they contrast wonderfully with the background...which looks, actually, B&W. Is this image the result of selective-color processing? If so, is such editing allowed in this challenge?', '2006-04-22 00:18:09.000000', NULL, 1),
(2334199, 323163, 27422, '<td valign="top">Seriously, your inch worm is a symbol of god''s love.</td>', 'Seriously, your inch worm is a symbol of god''s love.', '2006-04-22 00:18:16.000000', NULL, 1),
(2334202, 322320, 41574, '<td valign="top">I absolutely love the flatness and smoothness of the water (it is water, right?), and your composition is simply gorgeous. I don''t, however, know whether I feel this truly "fits" the challenge, or is just a stretch (through entitling) beyond reason. Ugh..."7."</td>', 'I absolutely love the flatness and smoothness of the water (it is water, right?), and your composition is simply gorgeous. I don''t, however, know whether I feel this truly "fits" the challenge, or is just a stretch (through entitling) beyond reason. Ugh..."7."', '2006-04-22 00:19:40.000000', NULL, 1),
(2334204, 321625, 27422, '<td valign="top">Fantastic. You are truely a person with immense patience.</td>', 'Fantastic. You are truely a person with immense patience.', '2006-04-22 00:20:34.000000', NULL, 1),
(2334208, 322919, 41574, '<td valign="top">Awww...how cute. I like the picture a lot, and appreciate your thoughtful composition. I think, however, that stronger colors could have really made this image stand out; quite a lot of beauty is lost in its flat, almost morose visuals. I <i>so</i> wish there were a way to hand out a "6.5"...umm, "6" it is. (Sorry.)</td>', 'Awww...how cute. I like the picture a lot, and appreciate your thoughtful composition. I think, however, that stronger colors could have really made this image stand out; quite a lot of beauty is lost in its flat, almost morose visuals. I so wish there were a way to hand out a "6.5"...umm, "6" it is. (Sorry.)', '2006-04-22 00:21:38.000000', NULL, 1),
(2334210, 323226, 41574, '<td valign="top">Great shot. And, the newness would be...?</td>', 'Great shot. And, the newness would be...?', '2006-04-22 00:22:02.000000', NULL, 1),
(2334212, 320481, 41574, '<td valign="top">So, what: is it a new shoe? Ahh, I just saw the tag. The shot, to me, looks indefensibly under-exposed; if under-exposure was a deliberate choice, I don''t see how it benefits the picture. I''d like to give it a "4.5," but shall have to settle on a...umm..."5."</td>', 'So, what: is it a new shoe? Ahh, I just saw the tag. The shot, to me, looks indefensibly under-exposed; if under-exposure was a deliberate choice, I don''t see how it benefits the picture. I''d like to give it a "4.5," but shall have to settle on a...umm..."5."', '2006-04-22 00:23:19.000000', NULL, 1),
(2334216, 323003, 41574, '<td valign="top">This looks like a respectable attempt at a macro, but the shot (I feel) doesn''t quite succeed. The focus on the main part of the flower (which feels like the center of attention) is weak; the dead-center framing doesn''t really add anything, and, in fact, takes away from appeal; the pinks in the background distract from the very strong pink of the subject; it just doesn''t stand a "winner." As I said, it looks to be a sincere, commendable try, but it falls short of "stellar."</td>', 'This looks like a respectable attempt at a macro, but the shot (I feel) doesn''t quite succeed. The focus on the main part of the flower (which feels like the center of attention) is weak; the dead-center framing doesn''t really add anything, and, in fact, takes away from appeal; the pinks in the background distract from the very strong pink of the subject; it just doesn''t stand a "winner." As I said, it looks to be a sincere, commendable try, but it falls short of "stellar."', '2006-04-22 00:25:46.000000', NULL, 1),
(2334220, 320187, 27422, '<td valign="top">Very vibrant.</td>', 'Very vibrant.', '2006-04-22 00:27:31.000000', NULL, 1),
(2334223, 321888, 41574, '<td valign="top">The subject fits the challenge perfectly, but, technically, the shot doesn''t appear to have been very carefully thought out. I understand that this is more a "record" picture than an "artful" one, but even with what it is, I feel it could have been better. Overall, it looks unappealingly under-exposed; the horizon looks tilted, which takes away from the prominence of the under-construction building; and the shot includes too much of the unnecessary background. Further, most of these issues could have  while not violating any rules  been addressed with some photo-editing software, prior to the entry''s submission. So, I like the image, but think it could have been much better.</td>', 'The subject fits the challenge perfectly, but, technically, the shot doesn''t appear to have been very carefully thought out. I understand that this is more a "record" picture than an "artful" one, but even with what it is, I feel it could have been better. Overall, it looks unappealingly under-exposed; the horizon looks tilted, which takes away from the prominence of the under-construction building; and the shot includes too much of the unnecessary background. Further, most of these issues could have  while not violating any rules  been addressed with some photo-editing software, prior to the entry''s submission. So, I like the image, but think it could have been much better.', '2006-04-22 00:28:53.000000', NULL, 1),
(2334224, 322607, 41574, '<td valign="top">I love these "magazine-type" shots; if nothing else, they stand as just so damned "professional." I''d be interested to hear how you went about pulling this off. Having said all this, I think it''s clear that I have nothing nut respect for the photograph in any "technical" regard. Insofar as its appropriateness for this challenge, I think it works only because of our knowledge of the marketing for the vehicle shown; as a self-contained image, the car wouldn''t strike me as something instantly thought of as "new." Then again, as an untitled image, I might just come to the conclusion that it is a new car, as it appears blemish-free, and stands proudly as though just brought home from the dealer. I guess, then, that I have little choice but to give you an outrageously high score. (Good job.)</td>', 'I love these "magazine-type" shots; if nothing else, they stand as just so damned "professional." I''d be interested to hear how you went about pulling this off. Having said all this, I think it''s clear that I have nothing nut respect for the photograph in any "technical" regard. Insofar as its appropriateness for this challenge, I think it works only because of our knowledge of the marketing for the vehicle shown; as a self-contained image, the car wouldn''t strike me as something instantly thought of as "new." Then again, as an untitled image, I might just come to the conclusion that it is a new car, as it appears blemish-free, and stands proudly as though just brought home from the dealer. I guess, then, that I have little choice but to give you an outrageously high score. (Good job.)', '2006-04-22 00:32:15.000000', NULL, 1),
(2334225, 323025, 41574, '<td valign="top">It''s like an "egg-o-lantern." I like it...I like it plenty.</td>', 'It''s like an "egg-o-lantern." I like it...I like it plenty.', '2006-04-22 00:32:55.000000', NULL, 1),
(2334228, 321495, 41574, '<td valign="top">I can''t express how distracting I find that moving leaf in the bottom right of the image. Seriously, it shatters any hopes I had for the picture as I viewed the thumbnail. Clearly, a faster shutter speed would have been an invaluable tool here.</td>', 'I can''t express how distracting I find that moving leaf in the bottom right of the image. Seriously, it shatters any hopes I had for the picture as I viewed the thumbnail. Clearly, a faster shutter speed would have been an invaluable tool here.', '2006-04-22 00:34:15.000000', NULL, 1),
(2334230, 322349, 41574, '<td valign="top">I''ve tried, and I can''t find a damned thing in this shot that makes it work as an entry to a challenge entitled, "Something New [III]." As a "candid," it''s nice, but it accomplishes little beyond that.</td>', 'I''ve tried, and I can''t find a damned thing in this shot that makes it work as an entry to a challenge entitled, "Something New [III]." As a "candid," it''s nice, but it accomplishes little beyond that.', '2006-04-22 00:35:52.000000', NULL, 1),
(2334231, 322926, 41574, '<td valign="top">Nice shot; really, really nice shot. Unfortunately, "clever entitling" doesn''t make it have anything to do with the theme of the challenge.</td>', 'Nice shot; really, really nice shot. Unfortunately, "clever entitling" doesn''t make it have anything to do with the theme of the challenge.', '2006-04-22 00:36:30.000000', NULL, 1),
(2334235, 323221, 41574, '<td valign="top">The white balance is <i>way</i> off here, and its being so hurts the picture significantly. Composition is nice, and clarity is appreciable, but I just don''t find any other reason to give it a great score.</td>', 'The white balance is way off here, and its being so hurts the picture significantly. Composition is nice, and clarity is appreciable, but I just don''t find any other reason to give it a great score.', '2006-04-22 00:38:44.000000', NULL, 1),
(2334237, 322972, 41574, '<td valign="top">A little brighter, with slightly more vibrant colors, and I''d have clicked the "10" as soon as I landed on this entry. In most regards, an absolutely stunning picture; I love it.</td>', 'A little brighter, with slightly more vibrant colors, and I''d have clicked the "10" as soon as I landed on this entry. In most regards, an absolutely stunning picture; I love it.', '2006-04-22 00:39:53.000000', NULL, 1),
(2334239, 320866, 41574, '<td valign="top">The subject looks indefensibly blurry to me, and the resolution seems to have been too low to have allowed the shot to have been blown up to this size. In other regards, it''s a nice attempt at a macro, but these flaws just stand out too strongly for me to give it anything more than a "3.5." Unfortunately, as there''s no option for giving such a grade, I''ll have to rely on my handy coin: the coin decides "3."</td>', 'The subject looks indefensibly blurry to me, and the resolution seems to have been too low to have allowed the shot to have been blown up to this size. In other regards, it''s a nice attempt at a macro, but these flaws just stand out too strongly for me to give it anything more than a "3.5." Unfortunately, as there''s no option for giving such a grade, I''ll have to rely on my handy coin: the coin decides "3."', '2006-04-22 00:41:57.000000', NULL, 1),
(2334243, 322989, 41574, '<td valign="top">I can''t help but feel I''m looking at an advertisement. If nothing else, you should demand a cheque from Apple. Nice picture, but too "commercial" to be judged as a "non-marketing" photograph.</td>', 'I can''t help but feel I''m looking at an advertisement. If nothing else, you should demand a cheque from Apple. Nice picture, but too "commercial" to be judged as a "non-marketing" photograph.', '2006-04-22 00:43:36.000000', NULL, 1),
