(2338589, 322640, 38032, '<td valign="top">Too contrived and snap-shottish.  Also seems insulting and a stretch to fit challenge.</td>', 'Too contrived and snap-shottish.  Also seems insulting and a stretch to fit challenge.', '2006-04-24 08:30:47.000000', NULL, 1),
(2338591, 323094, 38032, '<td valign="top">Great idea and  definitely fits challenge. Whether ot not this is real, It would be cooler in a more natural setting IMHO.</td>', 'Great idea and  definitely fits challenge. Whether ot not this is real, It would be cooler in a more natural setting IMHO.', '2006-04-24 08:32:25.000000', NULL, 1),
