(2383086, 322805, 12253, '<td valign="top">Beautiful. Good composition and perfect light and tones.</td>', 'Beautiful. Good composition and perfect light and tones.', '2006-05-04 20:08:34.000000', NULL, 0),
(2383943, 323164, 55642, '<td valign="top">I like how the center of the flower looks like a funnel, black hole of sorts. With teeth. Hah! I know this wasn''t really the intention, given that it''s a "Something New" shot, but today I''m just looking at flower pics as flowers and not one bit how they fit the challenges if they were challenge entries. I very likely would have cropped the white out of the upper left corner to enhance this effect, probably a slightly tighter square in which the flower fills the entire frame. Nice crisp focus on the center. You also win brownie points for the Italian, cuz I''m a total sucker. Mi piace li foto! Buona notte, amico! ;-)</td>', 'I like how the center of the flower looks like a funnel, black hole of sorts. With teeth. Hah! I know this wasn''t really the intention, given that it''s a "Something New" shot, but today I''m just looking at flower pics as flowers and not one bit how they fit the challenges if they were challenge entries. I very likely would have cropped the white out of the upper left corner to enhance this effect, probably a slightly tighter square in which the flower fills the entire frame. Nice crisp focus on the center. You also win brownie points for the Italian, cuz I''m a total sucker. Mi piace li foto! Buona notte, amico! ;-)', '2006-05-05 01:25:45.000000', NULL, 0),
(2384636, 320148, 58450, '<td valign="top">Great job, a very interesting photo!!</td>', 'Great job, a very interesting photo!!', '2006-05-05 08:35:54.000000', NULL, 0),
(2384731, 323015, 36060, '<td valign="top">Congrats on your ribbon!</td>', 'Congrats on your ribbon!', '2006-05-05 09:42:05.000000', NULL, 0),
